#### Phase 3: Health Check Implementation

**Step 3.1: Implement Health Check Endpoints**

Create comprehensive health check endpoints for load balancer health checks and smoke tests.

**Spring Boot Example (Java)**:

```java
@RestController
@RequestMapping("/health")
public class HealthCheckController {

    @Autowired
    private DataSource dataSource;

    @Autowired
    private KafkaTemplate kafkaTemplate;

    // Simple liveness check (for load balancer)
    @GetMapping
    public ResponseEntity<HealthStatus> health() {
        return ResponseEntity.ok(new HealthStatus("UP", "healthy"));
    }

    // Detailed readiness check (validates dependencies)
    @GetMapping("/ready")
    public ResponseEntity<DetailedHealthStatus> readiness() {
        DetailedHealthStatus status = new DetailedHealthStatus();
        status.setStatus("UP");

        // Check database connectivity
        try {
            Connection conn = dataSource.getConnection();
            conn.close();
            status.addCheck("database", "UP", "Connected");
        } catch (SQLException e) {
            status.setStatus("DOWN");
            status.addCheck("database", "DOWN", e.getMessage());
        }

        // Check Kafka connectivity
        try {
            kafkaTemplate.send("health-check-topic", "ping").get(5, TimeUnit.SECONDS);
            status.addCheck("kafka", "UP", "Connected");
        } catch (Exception e) {
            status.setStatus("DOWN");
            status.addCheck("kafka", "DOWN", e.getMessage());
        }

        // Return 503 if any dependency is down
        if ("DOWN".equals(status.getStatus())) {
            return ResponseEntity.status(HttpStatus.SERVICE_UNAVAILABLE).body(status);
        }

        return ResponseEntity.ok(status);
    }
}

@Data
class HealthStatus {
    private String status;
    private String message;

    public HealthStatus(String status, String message) {
        this.status = status;
        this.message = message;
    }
}

@Data
class DetailedHealthStatus {
    private String status;
    private Map<String, DependencyCheck> checks = new HashMap<>();

    public void addCheck(String dependency, String status, String message) {
        checks.put(dependency, new DependencyCheck(status, message));
    }
}

@Data
@AllArgsConstructor
class DependencyCheck {
    private String status;
    private String message;
}
```

**ASP.NET Core Example (C#)**:

```csharp
[ApiController]
[Route("health")]
public class HealthCheckController : ControllerBase
{
    private readonly IDbConnection _dbConnection;
    private readonly IKafkaProducer _kafkaProducer;

    public HealthCheckController(IDbConnection dbConnection, IKafkaProducer kafkaProducer)
    {
        _dbConnection = dbConnection;
        _kafkaProducer = kafkaProducer;
    }

    [HttpGet]
    public IActionResult Health()
    {
        return Ok(new { status = "UP", message = "healthy" });
    }

    [HttpGet("ready")]
    public async Task<IActionResult> Readiness()
    {
        var status = new DetailedHealthStatus { Status = "UP" };

        // Check database
        try
        {
            await _dbConnection.OpenAsync();
            _dbConnection.Close();
            status.Checks["database"] = new DependencyCheck { Status = "UP", Message = "Connected" };
        }
        catch (Exception ex)
        {
            status.Status = "DOWN";
            status.Checks["database"] = new DependencyCheck { Status = "DOWN", Message = ex.Message };
        }

        // Check Kafka
        try
        {
            await _kafkaProducer.ProduceAsync("health-check-topic", "ping");
            status.Checks["kafka"] = new DependencyCheck { Status = "UP", Message = "Connected" };
        }
        catch (Exception ex)
        {
            status.Status = "DOWN";
            status.Checks["kafka"] = new DependencyCheck { Status = "DOWN", Message = ex.Message };
        }

        if (status.Status == "DOWN")
        {
            return StatusCode(503, status);
        }

        return Ok(status);
    }
}

public class DetailedHealthStatus
{
    public string Status { get; set; }
    public Dictionary<string, DependencyCheck> Checks { get; set; } = new();
}

public class DependencyCheck
{
    public string Status { get; set; }
    public string Message { get; set; }
}
```

