#### Phase 4: Testing Strategy

**Step 4.1: Create Smoke Test Suite**

Develop automated smoke tests to validate basic functionality in Green environment before cutover.

**k6 Load Test Example (`tests/smoke-tests.js`)**:

```javascript
import http from 'k6/http';
import { check, sleep } from 'k6';

export let options = {
  vus: 1,  // Single virtual user for smoke test
  duration: '30s',
  thresholds: {
    'http_req_duration': ['p(95)<2000'],  // 95% of requests must complete in <2s
    'http_req_failed': ['rate<0.01'],     // Error rate must be <1%
  },
};

const BASE_URL = __ENV.BASE_URL || 'https://green-internal.gainwell.com';

export default function () {
  // Test 1: Health Check
  let healthRes = http.get(`${BASE_URL}/health`);
  check(healthRes, {
    'health check returns 200': (r) => r.status === 200,
    'health check returns healthy': (r) => JSON.parse(r.body).status === 'UP',
  });

  // Test 2: Readiness Check
  let readyRes = http.get(`${BASE_URL}/health/ready`);
  check(readyRes, {
    'readiness check returns 200': (r) => r.status === 200,
    'readiness check database UP': (r) => JSON.parse(r.body).checks.database.status === 'UP',
  });

  // Test 3: Create Claim (POST)
  let createRes = http.post(`${BASE_URL}/api/v1/claims`, JSON.stringify({
    providerId: 'PRV123456',
    memberId: 'MEM789012',
    serviceDate: '2025-01-15',
    amount: 125.50,
    cptCode: '99213'
  }), {
    headers: { 'Content-Type': 'application/json' },
  });
  check(createRes, {
    'create claim returns 201': (r) => r.status === 201,
    'create claim returns claim ID': (r) => JSON.parse(r.body).claimId != null,
  });

  let claimId = JSON.parse(createRes.body).claimId;

  // Test 4: Get Claim (GET)
  let getRes = http.get(`${BASE_URL}/api/v1/claims/${claimId}`);
  check(getRes, {
    'get claim returns 200': (r) => r.status === 200,
    'get claim returns correct ID': (r) => JSON.parse(r.body).claimId === claimId,
  });

  sleep(1);
}
```

**Step 4.2: Create Load Test Suite**

Develop load tests to simulate production traffic patterns.

**k6 Load Test Example (`tests/load-test.js`)**:

```javascript
import http from 'k6/http';
import { check, sleep } from 'k6';

export let options = {
  stages: [
    { duration: '2m', target: 50 },   // Ramp up to 50 VUs over 2 minutes
    { duration: '5m', target: 50 },   // Stay at 50 VUs for 5 minutes
    { duration: '2m', target: 100 },  // Ramp up to 100 VUs over 2 minutes
    { duration: '5m', target: 100 },  // Stay at 100 VUs for 5 minutes (peak load)
    { duration: '2m', target: 0 },    // Ramp down to 0 VUs over 2 minutes
  ],
  thresholds: {
    'http_req_duration': ['p(95)<2000', 'p(99)<4000'],  // P95 <2s, P99 <4s
    'http_req_failed': ['rate<0.005'],                   // Error rate <0.5%
  },
};

const BASE_URL = __ENV.BASE_URL || 'https://green-internal.gainwell.com';

// Simulate realistic traffic patterns
export default function () {
  // 60% reads, 40% writes (typical claims API pattern)
  let random = Math.random();

  if (random < 0.6) {
    // Read operation: Get claim by ID
    let claimId = `CLM${Math.floor(Math.random() * 1000000)}`;
    let res = http.get(`${BASE_URL}/api/v1/claims/${claimId}`);
    check(res, {
      'get claim status is 200 or 404': (r) => r.status === 200 || r.status === 404,
      'get claim latency acceptable': (r) => r.timings.duration < 2000,
    });
  } else {
    // Write operation: Create claim
    let res = http.post(`${BASE_URL}/api/v1/claims`, JSON.stringify({
      providerId: `PRV${Math.floor(Math.random() * 100000)}`,
      memberId: `MEM${Math.floor(Math.random() * 1000000)}`,
      serviceDate: '2025-01-15',
      amount: Math.random() * 500,
      cptCode: ['99213', '99214', '99215'][Math.floor(Math.random() * 3)]
    }), {
      headers: { 'Content-Type': 'application/json' },
    });
    check(res, {
      'create claim status is 201': (r) => r.status === 201,
      'create claim latency acceptable': (r) => r.timings.duration < 3000,
    });
  }

  sleep(1);  // Think time between requests
}
```
